def subarray_sum_brute(nums: list[int], k: int) -> int:
    """Given: the O(n^2) brute force, used by the tests as a reference."""
    count = 0
    for i in range(len(nums)):
        total = 0
        for j in range(i, len(nums)):
            total += nums[j]
            if total == k:
                count += 1
    return count

