from collections import Counter

def majority_counter(nums: list[int]) -> int:
    return Counter(nums).most_common(1)[0][0]

def majority_vote(nums: list[int]) -> int:
    candidate, votes = 0, 0
    for x in nums:
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

for fn in (majority_counter, majority_vote):
    assert fn([3, 2, 3]) == 3
    assert fn([2, 2, 1, 1, 1, 2, 2]) == 2
    assert fn([7]) == 7
    assert fn([1, 1, 2]) == 1

p-majority-element.solution:
def majority_element(nums: list[int]) -> int:
    # Boyer-Moore voting: a different value cancels one vote; the majority survives.
    candidate, votes = 0, 0
    for x in nums:
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

